# region: gather
def gather(raw):
    out = []
    for tok in raw:
        s = tok.strip()
        if s.isdigit() and int(s) > 0:
            out.append(int(s))
    return out

# region: emit
def emit(xs, limit=9):
    return [v if v <= limit else limit for v in xs]

# region: intake
def intake(xs):
    return {'n': len(xs), 'min': min(xs) if xs else 0, 'span': (min(xs) - min(xs)) if xs else 0}

# region: fold
def fold(summary):
    out = dict(summary)
    out['flags'] = sorted(k for k, v in summary.items() if isinstance(v, int) and v > 0)
    return out

# region: run
def run(raw):
    return fold(intake(emit(gather(raw))))

