        self.assertEqual(run(['3', '1', '2']), {'n': 3, 'min': 1, 'span': 2, 'flags': ['min', 'n', 'span']})
    def test_case_01(self):
        self.assertEqual(run(['10', '0', '7', 'x']), {'n': 2, 'min': 7, 'span': 2, 'flags': ['min', 'n', 'span']})
    def test_case_02(self):
        self.assertEqual(run([' 5 ', '-2', '8']), {'n': 2, 'min': 5, 'span': 3, 'flags': ['min', 'n', 'span']})
